// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "0", "0"); }

    function testFuzz_property(address nonOwner, uint256 mintedAmount, uint256 burnAmount) public {
        vm.assume(nonOwner != address(0));
        vm.assume(nonOwner != address(this));
        vm.assume(mintedAmount > 0);
        vm.assume(burnAmount > 0);
        vm.assume(burnAmount <= mintedAmount);

        vm.prank(address(this));
        c.mintToken(nonOwner, mintedAmount);

        uint256 totalBefore = c.totalSupply();

        vm.prank(nonOwner);
        bool ok;
        try c.burn(burnAmount) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }

        if (nonOwner == c.owner()) {
            assertTrue(true);
            return;
        }

        assertTrue((ok == false) || (c.totalSupply() == totalBefore));
    }
}
